intentos.respuesta_cruda:
{
  "sql": "SELECT rango_retraso, COUNT(order_id) AS pedidos, ROUND(100.0 * SUM(CASE WHEN review_score <= 2 THEN 1 ELSE 0 END) / COUNT(order_id), 2) AS pct_calif_2_o_menos, ROUND(100.0 * SUM(CASE WHEN rango_retraso = 'a_tiempo' THEN 1 ELSE 0 END) / COUNT(order_id), 2) AS pct_calif_2_o_menos_a_tiempo FROM vw_entregas_retrasos WHERE rango_retraso IN ('a_tiempo', '1-3', '4-7', '8-14', '15+') GROUP BY rango_retraso HAVING pct_calif_2_o_menos >= 2 * pct_calif_2_o_menos_a_tiempo"
}
